// Clean and normalize user message text
const rawMessage = $json.userMessage || '';

// Remove extra whitespace, normalize line breaks
let cleanedMessage = rawMessage
  .replace(/\s+/g, ' ')       // Collapse multiple spaces
  .replace(/\n+/g, ' ')       // Replace newlines with space
  .trim();                     // Remove leading/trailing whitespace

return {
  ...$json,
  cleanedMessage: cleanedMessage,
  messageWordCount: cleanedMessage.split(' ').filter(w => w.length > 0).length
};

// Standardize and consolidate all lead data
const leadData = $json.leadData || {};
const aiClassification = $json.aiClassification || {};

return {
  // Original lead info
  name: (leadData.leadName || '').trim(),
  email: (leadData.leadEmail || '').toLowerCase().trim(),
  phone: (leadData.leadPhone || '').replace(/[^0-9+]/g, ''),
  propertyAddress: (leadData.propertyAddress || '').trim(),

  // Message data
  originalMessage: leadData.userMessage || '',
  cleanedMessage: leadData.cleanedMessage || '',
  messageWordCount: leadData.messageWordCount || 0,

  // AI classification
  intent: aiClassification.intent || 'unknown',
  urgency: aiClassification.urgency || 'low',
  intentConfidence: aiClassification.intentConfidence || 0,
  summary: aiClassification.summary || '',
  keyDetails: aiClassification.keyDetails || [],

  // Metadata
  receivedAt: leadData.receivedAt || new Date().toISOString(),
  source: 'web_form'
};

// Calculate lead score for known listing
const leadData = $('Standardize All Lead Data Fields').item.json;
const propertyData = $json;

let score = 0;
const scoreBreakdown = [];

// Known listing bonus (+25)
score += 25;
scoreBreakdown.push({ factor: 'Known Listing', points: 25 });

// Intent scoring
const intentScores = { buying: 30, selling: 25, renting: 15, inquiry: 10, other: 5 };
const intentPoints = intentScores[leadData.intent] || 5;
score += intentPoints;
scoreBreakdown.push({ factor: `Intent: ${leadData.intent}`, points: intentPoints });

// Urgency scoring
const urgencyScores = { high: 25, medium: 15, low: 5 };
const urgencyPoints = urgencyScores[leadData.urgency] || 5;
score += urgencyPoints;
scoreBreakdown.push({ factor: `Urgency: ${leadData.urgency}`, points: urgencyPoints });

// Contact info completeness
if (leadData.email) { score += 5; scoreBreakdown.push({ factor: 'Has Email', points: 5 }); }
if (leadData.phone) { score += 5; scoreBreakdown.push({ factor: 'Has Phone', points: 5 }); }

// AI confidence bonus
if (leadData.intentConfidence > 0.8) {
  score += 10;
  scoreBreakdown.push({ factor: 'High AI Confidence', points: 10 });
}

// Determine priority tier
let priority = 'Low';
if (score >= 70) priority = 'Hot';
else if (score >= 50) priority = 'Warm';
else if (score >= 30) priority = 'Medium';

return {
  ...leadData,
  propertyMatch: propertyData,
  isKnownListing: true,
  leadScore: score,
  priority: priority,
  scoreBreakdown: scoreBreakdown,
  scoredAt: new Date().toISOString()
};

