const intentScores = { buying: 30, selling: 25, renting: 15, inquiry: 10, other: 5 };
const intentPoints = intentScores[leadData.intent] || 5;
score += intentPoints;
scoreBreakdown.push({ factor: `Intent: ${leadData.intent}`, points: intentPoints });

